/// Parity: everything the prior plugin refused is still refused.
#[test]
fn parity_with_prior_list() {
    let pol = policy();
    let prior: Vec<Value> =
        serde_json::from_str(include_str!("denylist/prior-results.json")).unwrap();
    let mut n = 0;
    for c in prior.iter().filter(|c| c["prior"] == "BLOCKED") {
        n += 1;
        let r = verdict(c["tool"].as_str().unwrap(), &c["params"], &pol);
        assert!(r.is_err(), "prior refused but new allows: {}", c["params"]);
    }
    assert!(n >= 60, "expected the prior-blocked set, got {n}");
}

/// The six cases of the prior `test-guard.sh`.
#[test]
fn prior_test_guard_sh_cases() {
    let pol = policy();
    assert!(check_command("rm -rf /", &pol).is_err());
    assert!(check_command("git push --force", &pol).is_err());
    assert!(check_command("ls -la", &pol).is_ok());
    assert!(check_command("git status", &pol).is_ok());
    assert!(check_command("rm -rf node_modules", &pol).is_ok());
    assert!(check_command("cat /workspace/galion-light/secrets/hermes.key", &pol).is_err());
}

/// Every one of the 57 prior list rules and 12 floor rules still fires on a
/// sample that it alone was written for (spot check on the prior list file).
#[test]
fn prior_rules_are_loaded_verbatim() {
    let p = hermes_rs::denylist::rules::prior();
    assert_eq!(p.list.len(), 57, "55 galion + 2 ondrej extra rules");
    assert_eq!(p.floor.len(), 12);
}

#[test]
fn allowlist_mode_is_default_deny() {
    let mut pol = policy();
    pol.mode = Mode::Allowlist;
    for ok in [
        "ls -la",
        "rg -n deny docs/",
        "git status",
        "cat README.md | wc -l",
    ] {
        assert!(check_command(ok, &pol).is_ok(), "{ok}");
    }
    for bad in [
        "strings bin/x",
        "hexdump -C x",
        "od -c x",
        "column2 x",
        "convert a.png b.png",
    ] {
        assert!(check_command(bad, &pol).is_err(), "{bad}");
    }
    // the denylist mode lets those unknown-but-harmless words through
    pol.mode = Mode::Denylist;
    assert!(check_command("hexdump -C x", &pol).is_ok());
}

#[test]
fn no_workspace_means_no_writes() {
    let pol = Policy {
        write_roots: Vec::new(),
        ..policy()
    };
    assert!(check_command("echo ok > out.txt", &pol).is_err());
    assert!(check_tool_call("fs_write", &json!({"path":"src/a.rs","content":"x"}), &pol).is_err());
    assert!(check_command("cat src/lib.rs", &pol).is_ok());
}

#[test]
fn write_roots_never_cover_secrets_or_the_vault() {
    for bad in [
        "/",
        "/opt",
        "/opt/galion/hermes",
        "/opt/galion/galion-light/docs/build-session",
        "/root/.ssh",
    ] {
        let p = Policy::workspace(bad);
        assert!(p.write_roots.is_empty(), "{bad} must not become writable");
    }
}

#[test]
fn symlink_out_of_workspace_is_resolved() {
    let ws = workspace();
    let link = ws.join("escape-link");
    let _ = std::fs::remove_file(&link);
    std::os::unix::fs::symlink("/root", &link).unwrap();
    let pol = policy();
    assert!(check_command("echo x > escape-link/.bashrc", &pol).is_err());
    assert!(check_tool_call(
        "fs_write",
        &json!({"path":"escape-link/x","content":"y"}),
        &pol
    )
    .is_err());
    assert!(check_command("cd escape-link", &pol).is_err());
    std::fs::remove_file(&link).unwrap();
}

#[test]
fn hostile_inputs_fail_closed() {
    let pol = policy();
    let big = "a ".repeat(20_000);
    assert!(check_command(&big, &pol).is_err());
    let mut v = json!("x");
    for _ in 0..64 {
        v = json!({ "a": v });
    }
    assert!(check_tool_call("lookup", &v, &pol).is_err());
    // a shell tool with nothing inspectable
    assert!(check_tool_call("terminal", &json!({"input": "rm -rf /"}), &pol).is_err());
    // argv arrays are checked as words
    assert!(check_tool_call("exec", &json!({"argv": ["rm", "-rf", "/root"]}), &pol).is_err());
    assert!(check_tool_call("exec", &json!({"argv": ["ls", "-la"]}), &pol).is_ok());
}

// ------------------------------------------------ the registry chokepoint

mod chokepoint {
    use super::*;
    use hermes_rs::config::Config;
    use hermes_rs::delegate::DelegateTool;
    use hermes_rs::provider::{ChatResult, MockProvider, ToolCall};
    use hermes_rs::spend::SpendTracker;
    use hermes_rs::tools::{Registry, Tool, ToolCtx, ToolOutput};
    use std::path::Path;
    use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
    use std::sync::Arc;

    /// A write tool that counts how often it really ran.
    struct FakeWrite(Arc<AtomicUsize>, &'static str);
    impl Tool for FakeWrite {
        fn name(&self) -> String {
            self.1.into()
        }
        fn parameters(&self) -> Value {
            json!({"type":"object"})
        }
        fn description(&self) -> String {
            "write a file".into()
        }
        fn call(&self, _a: &Value, _c: &ToolCtx) -> ToolOutput {
            self.0.fetch_add(1, Ordering::SeqCst);
            ToolOutput::ok("written")
        }
    }

    fn ctx_call(t: &dyn Tool, args: Value, user: &str) -> ToolOutput {
        let cancel = Arc::new(AtomicBool::new(false));
        let ctx = ToolCtx {
            session_id: "s",
            spend_session: "s",
            depth: 0,
            user_text: user,
            cancel: &cancel,
            emit: &|_e| {},
        };
        t.call(&args, &ctx)
    }

    const VAULT_NOTE: &str = "/opt/galion/galion-light/docs/build-session/memory-test.md";

    #[test]
    fn registry_wraps_every_tool() {
        let ran = Arc::new(AtomicUsize::new(0));
        let mut reg = Registry::with_policy(policy());
        reg.add(Arc::new(FakeWrite(ran.clone(), "fs_write")));
        reg.add(Arc::new(FakeWrite(
            ran.clone(),
            "mcp__openmind__vault_write",
        )));
        let t = reg.get("fs_write").unwrap();
        let out = ctx_call(&*t, json!({"path": VAULT_NOTE, "content": "x"}), "");
        assert!(
            out.is_error && out.content.contains("blocked by the Hermes deny list"),
            "{}",
            out.content
        );
        let out = ctx_call(&*t, json!({"path": "src/ok.rs", "content": "x"}), "");
        assert!(!out.is_error, "{}", out.content);
        let t = reg.get("mcp__openmind__vault_write").unwrap();
        assert!(ctx_call(&*t, json!({"path": "n.md", "content": "x"}), "").is_error);
        assert_eq!(
            ran.load(Ordering::SeqCst),
            1,
            "only the in-workspace write ran"
        );
        // the child registry a delegate gets keeps the wrapper
        let child = reg.without("delegate_task");
        let t = child.get("fs_write").unwrap();
        assert!(ctx_call(&*t, json!({"path": VAULT_NOTE, "content": "x"}), "").is_error);
        assert_eq!(ran.load(Ordering::SeqCst), 1);
    }

    fn delegate(child_tools: Registry, mock: MockProvider) -> (DelegateTool, Arc<MockProvider>) {
        let cfg = Arc::new(Config::defaults(Path::new("/tmp")));
        let mock = Arc::new(mock);
        let spend = Arc::new(SpendTracker::new(cfg.spend.clone(), None));
        (
            DelegateTool::new(cfg, mock.clone(), spend, child_tools)
                .with_policy(Arc::new(policy())),
            mock,
        )
    }

    /// The live-test scenario: Hermes refuses a vault write, then offers to
    /// route it through its coding agent. (a) the delegate call that asks for
    /// it is refused before any child runs; (b) a child that tries the write
    /// on its own (innocent-looking goal) is refused at the same chokepoint.
    #[test]
    fn delegated_vault_write_is_refused_end_to_end() {
        let ran = Arc::new(AtomicUsize::new(0));
        let mut base = Registry::with_policy(policy());
        base.add(Arc::new(FakeWrite(ran.clone(), "fs_write")));

        // child model: always tries to write the vault note, then reports
        let child_mock = MockProvider::new(|_t, r| {
            let last = r.messages.last().cloned().unwrap_or(Value::Null);
            if last["role"] == "tool" {
                return ChatResult {
                    content: format!("tool said: {}", last["content"].as_str().unwrap_or("")),
                    finish_reason: "stop".into(),
                    ..Default::default()
                };
            }
            ChatResult {
                tool_calls: vec![ToolCall {
                    id: "c1".into(),
                    name: "fs_write".into(),
                    arguments: json!({"path": VAULT_NOTE, "content": "note"}).to_string(),
                }],
                finish_reason: "tool_calls".into(),
                ..Default::default()
            }
        });
        let (dt, mock) = delegate(base.clone(), child_mock);

        // (a) through the registry: the delegate call itself is refused
        let mut reg = base.clone();
        reg.add(Arc::new(dt));
        let t = reg.get("delegate_task").unwrap();
        let out = ctx_call(
            &*t,
            json!({"tasks": [{"goal": format!("Use the coding agent to write the note to {VAULT_NOTE}")}]}),
            "use a helper please",
        );
        assert!(
            out.is_error && out.content.contains("deny list"),
            "{}",
            out.content
        );
        let out = ctx_call(
            &*t,
            json!({"tasks": [{"goal": "Save this as a vault note: user prefers tea"}]}),
            "use a helper please",
        );
        assert!(
            out.is_error && out.content.contains("S9-vault-write"),
            "{}",
            out.content
        );
        assert_eq!(mock.calls.lock().unwrap().len(), 0, "no child ran");

        // (b) innocent goal, child tries the write itself: refused inside the child
        let out = ctx_call(
            &*t,
            json!({"tasks": [{"goal": "tidy up the meeting notes"}]}),
            "use a helper please",
        );
        assert!(!out.is_error, "{}", out.content);
        assert!(
            out.content.contains("blocked by the Hermes deny list"),
            "{}",
            out.content
        );
        assert_eq!(ran.load(Ordering::SeqCst), 0, "the vault write never ran");
    }

    /// Fix 4 (partial rerun): a call that mixes a refused vault-write task
    /// with a safe task runs the safe task and reports the other as refused,
    /// instead of failing the whole call. Guard lets the mixed call through
    /// (not every task is refused); DelegateTool enforces per task.
    #[test]
    fn partial_rerun_runs_safe_task_when_one_refused() {
        let base = Registry::with_policy(policy());
        let child_mock = MockProvider::new(|_t, _r| ChatResult {
            content: "the sum is 6".into(),
            finish_reason: "stop".into(),
            ..Default::default()
        });
        let (dt, mock) = delegate(base.clone(), child_mock);
        let mut reg = base.clone();
        reg.add(Arc::new(dt));
        let t = reg.get("delegate_task").unwrap();
        let out = ctx_call(
            &*t,
            json!({"tasks": [
                {"goal": "Save this as a vault note: user prefers tea"},
                {"goal": "Add 1, 2 and 3 and report the total."}
            ]}),
            "use a helper please",
        );
        assert!(
            !out.is_error,
            "mixed call must not fail wholesale: {}",
            out.content
        );
        let v: Value = serde_json::from_str(&out.content).unwrap();
        let results = v["results"].as_array().unwrap();
        assert_eq!(results.len(), 2, "{}", out.content);
        assert_eq!(results[0]["status"], "refused", "{}", out.content);
        assert!(
            results[0]["error"]
                .as_str()
                .unwrap()
                .contains("S9-vault-write"),
            "{}",
            out.content
        );
        assert_eq!(results[1]["status"], "completed", "{}", out.content);
        assert_eq!(
            mock.calls.lock().unwrap().len(),
            1,
            "only the safe task ran"
        );
    }
}

/// `cargo test --test denylist_bypass -- --ignored --nocapture dump` prints
/// the rule that refused each payload (used for the report table).
#[test]
#[ignore]
fn dump_rules_per_case() {
    let pol = policy();
    for c in corpus() {
        let r = verdict(c["tool"].as_str().unwrap(), &c["params"], &pol);
        println!(
            "{}\t{}\t{}\t{}",
            c["class"].as_str().unwrap(),
            c["tool"].as_str().unwrap(),
            r.err().unwrap_or_else(|| "ALLOW".into()),
            c["params"]
        );
    }
}

